DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.claim_decision_execution(uuid,boolean)'::regprocedure) INTO definition; definition:=replace(definition,'SELECT * INTO q FROM public.ai_action_queue WHERE id=d.source_id FOR UPDATE;','SELECT * INTO q FROM public.ai_action_queue WHERE id=d.source_id FOR UPDATE; IF q.type IN (''client_email'',''payment_link'') AND (q.reviewed_by IS NULL OR q.reviewed_at IS NULL OR public.is_agent_user(q.reviewed_by)) THEN RAISE EXCEPTION ''Execução exige aprovação humana anterior no Cockpit'' USING ERRCODE=''42501''; END IF;'); EXECUTE definition; END $$;